const input = $input.first().json || {};

let normalizedLead = input.normalized_lead || {};
let deduplication = input.deduplication || {};

if (typeof normalizedLead === "string") {
  normalizedLead = JSON.parse(normalizedLead);
}

if (typeof deduplication === "string") {
  deduplication = JSON.parse(deduplication);
}

function clean(value) {
  if (value === undefined || value === null) return null;
  const text = String(value).trim();
  return text.length ? text : null;
}

function normalizeDomain(value) {
  const text = clean(value);
  if (!text) return null;

  return text
    .replace(/^https?:\/\//i, "")
    .replace(/^www\./i, "")
    .split("/")[0]
    .toLowerCase();
}

const eventId = Number(input.event_id || input.run_id);
const leadId = Number(input.lead_id);

if (!eventId || Number.isNaN(eventId)) {
  throw new Error("Missing valid event_id/run_id");
}

if (!leadId || Number.isNaN(leadId)) {
  throw new Error("Missing valid lead_id from Workflow 02");
}

const leadEmail = clean(input.lead_email || normalizedLead.email);

const companyDomain = normalizeDomain(
  input.company_domain ||
  normalizedLead.company_domain ||
  (
    leadEmail && leadEmail.includes("@")
      ? leadEmail.split("@")[1]
      : null
  )
);

const websiteUrl =
  clean(input.website_url || normalizedLead.website_url) ||
  (companyDomain ? `https://${companyDomain}` : null);

const leadName =
  clean(input.lead_name || normalizedLead.full_name) ||
  [
    clean(normalizedLead.first_name),
    clean(normalizedLead.last_name)
  ].filter(Boolean).join(" ") ||
  null;

return [
  {
    json: {
      run_id: eventId,
      event_id: eventId,
      external_id: clean(input.external_id || normalizedLead.external_id),
      event_source: clean(input.event_source || normalizedLead.source) || "website_form",

      lead_id: leadId,
      lead_name: leadName,
      lead_email: leadEmail,
      lead_phone: clean(input.lead_phone || normalizedLead.phone),
      lead_source: clean(input.lead_source || input.event_source || normalizedLead.source) || "website_form",

      company_name: clean(input.company_name || normalizedLead.company_name),
      company_domain: companyDomain,
      website_url: websiteUrl,

      job_title: clean(input.job_title || normalizedLead.job_title),
      message: clean(input.message || normalizedLead.message),
      budget: clean(input.budget || normalizedLead.budget),
      timeline: clean(input.timeline || normalizedLead.timeline),
      country: clean(input.country || normalizedLead.country),

      normalized_lead: normalizedLead,
      deduplication
    }
  }
];

const input = $('Normalize Enrichment Input').first().json;

return [
  {
    json: {
      ...input,
      website_fetch_status: "not_available",
      website_text: ""
    }
  }
];

