parameters.jsCode:
const raw =
  $json.output ||
  $json.text ||
  $json.content ||
  $json.message ||
  JSON.stringify($json);

const input = $('Build Lead Context').first().json;

function cleanText(value) {
  if (!value) return "";
  return String(value).trim();
}

function normalizeArray(value) {
  if (!value) return [];
  if (Array.isArray(value)) {
    return value.map(v => String(v).trim()).filter(Boolean);
  }
  return [String(value).trim()].filter(Boolean);
}

function normalizeValue(value, allowed, fallback) {
  const clean = cleanText(value);
  return allowed.includes(clean) ? clean : fallback;
}

function parseJsonFromText(value) {
  let text = String(value || "").trim();

  text = text
    .replace(/^```json/i, "")
    .replace(/^```/i, "")
    .replace(/```$/i, "")
    .trim();

  const first = text.indexOf("{");
  const last = text.lastIndexOf("}");

  if (first !== -1 && last !== -1) {
    text = text.slice(first, last + 1);
  }

  return JSON.parse(text);
}

const parsed = parseJsonFromText(raw);

const enrichment = {
  person: {
    job_title: cleanText(parsed.person?.job_title || input.job_title),
    department_estimate: cleanText(parsed.person?.department_estimate),
    seniority_estimate: cleanText(parsed.person?.seniority_estimate),
    decision_maker_likelihood: normalizeValue(
      parsed.person?.decision_maker_likelihood,
      ["low", "medium", "high"],
      "low"
    )
  },

  company: {
    company_name: cleanText(parsed.company?.company_name || input.company_name),
    company_domain: cleanText(parsed.company?.company_domain || input.company_domain),
    website_url: cleanText(parsed.company?.website_url || input.website_url),
    industry: cleanText(parsed.company?.industry),
    company_size_estimate: cleanText(parsed.company?.company_size_estimate),
    country: cleanText(parsed.company?.country || input.country),
    business_model: cleanText(parsed.company?.business_model)
  },

  intent: {
    detected_use_case: cleanText(parsed.intent?.detected_use_case),
    automation_pain_points: normalizeArray(parsed.intent?.automation_pain_points),
    buying_intent_signals: normalizeArray(parsed.intent?.buying_intent_signals),
    urgency_signals: normalizeArray(parsed.intent?.urgency_signals),
    budget_signal: cleanText(parsed.intent?.budget_signal || input.budget),
    timeline_signal: cleanText(parsed.intent?.timeline_signal || input.timeline)
  },

  routing_context: {
    positive_fit_signals: normalizeArray(parsed.routing_context?.positive_fit_signals),
    negative_fit_signals: normalizeArray(parsed.routing_context?.negative_fit_signals),
    recommended_routing_context: cleanText(parsed.routing_context?.recommended_routing_context),
    missing_information: normalizeArray(parsed.routing_context?.missing_information),
    enrichment_confidence: normalizeValue(
      parsed.routing_context?.enrichment_confidence,
      ["low", "medium", "high"],
      "low"
    )
  },

  metadata: {
    website_fetched: Boolean(input.website_text),
    website_text_length: String(input.website_text || "").length,
    enriched_at: new Date().toISOString()
  }
};

return [
  {
    json: {
      ...input,
      enrichment
    }
  }
];

const input = $('Normalize Enrichment Input').first().json;
const current = $input.first().json || {};

function clean(value) {
  if (value === undefined || value === null) return "";
  return String(value).trim();
}

function stripHtml(html) {
  return clean(html)
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/\s+/g, " ")
    .trim();
}

let websiteText = "";

if (typeof current === "string") {
  websiteText = stripHtml(current);
} else if (current.body) {
  websiteText = stripHtml(current.body);
} else if (current.data) {
  websiteText = stripHtml(current.data);
} else if (current.website_text) {
  websiteText = stripHtml(current.website_text);
}

if (websiteText.length > 6000) {
  websiteText = websiteText.slice(0, 6000);
}

const leadContext = {
  person: {
    lead_id: input.lead_id,
    lead_name: input.lead_name,
    lead_email: input.lead_email,
    lead_phone: input.lead_phone,
    job_title: input.job_title,
    country: input.country,
    source: input.lead_source
  },

  company: {
    company_name: input.company_name,
    company_domain: input.company_domain,
    website_url: input.website_url
  },

  request: {
    message: input.message,
    budget: input.budget,
    timeline: input.timeline
  },

  website: {
    fetched: Boolean(websiteText),
    text: websiteText
  },

  source: {
    event_id: input.event_id,
    external_id: input.external_id,
    event_source: input.event_source
  },

  deduplication: input.deduplication || {}
};

return [
  {
    json: {
      ...input,
      website_text: websiteText,
      lead_context: leadContext,
      enrichment_prompt: JSON.stringify(leadContext)
    }
  }
];
